1	import * as TabsPrimitive from "@radix-ui/react-tabs";
2	import {
3	  forwardRef,
4	  type ComponentPropsWithoutRef,
5	  type ComponentRef,
6	} from "react";
7	import { cn } from "../../utils/cn";
8	import { ButtonText } from "../Text";
9	import { toggleOptionVariants } from "../Toggle/toggleOption";
10	import type { TabSize, TabVariant } from "./constants";
11	
12	const TabsRoot = TabsPrimitive.Root;
13	
14	const TabsList = forwardRef<
15	  ComponentRef<typeof TabsPrimitive.List>,
16	  ComponentPropsWithoutRef<typeof TabsPrimitive.List>
17	>(({ className, ...props }, ref) => (
18	  <TabsPrimitive.List
19	    ref={ref}
20	    className={cn("inline-flex items-center gap-xxs", className)}
21	    {...props}
22	  />
23	));
24	TabsList.displayName = "TabsList";
25	
26	/** Kept under its historical name: TabsTrigger IS the Figma Toggle Option. */
27	const tabTriggerVariants = toggleOptionVariants;
28	
29	// TabSize / TabVariant (+ their types) live in ./constants — kept server-safe
30	// (no "use client") so RSC code can read the enum values. Re-exported via index.ts.
31	
32	/* `size` / `variant` are typed from the `TabSize` / `TabVariant` consts, not
33	 * cva's `VariantProps`: that admits `null`, which cva reads as "no variant"
34	 * (an unsized or unfilled tab). */
35	export interface TabsTriggerProps
36	  extends ComponentPropsWithoutRef<typeof TabsPrimitive.Trigger> {
37	  /** Defaults to `standard`. */
38	  size?: TabSize;
39	  /** Defaults to `ghost`. */
40	  variant?: TabVariant;
41	}
42	
43	const TabsTrigger = forwardRef<
44	  ComponentRef<typeof TabsPrimitive.Trigger>,
45	  TabsTriggerProps
46	>(({ className, size, variant, ...props }, ref) => (
47	  <ButtonText
48	    as={TabsPrimitive.Trigger}
49	    ref={ref}
50	    className={cn(tabTriggerVariants({ size, variant }), className)}
51	    {...props}
52	  />
53	));
54	TabsTrigger.displayName = "TabsTrigger";
55	
56	const TabsContent = forwardRef<
57	  ComponentRef<typeof TabsPrimitive.Content>,
58	  ComponentPropsWithoutRef<typeof TabsPrimitive.Content>
59	>(({ className, ...props }, ref) => (
60	  <TabsPrimitive.Content
61	    ref={ref}
62	    className={cn("ds-focus-visible-ring", className)}
63	    {...props}
64	  />
65	));
66	TabsContent.displayName = "TabsContent";
67	
68	export { TabsRoot as Tabs, TabsContent, TabsList, TabsTrigger, tabTriggerVariants };
69

